//! A service map: services, the repositories holding their code, and their main runtime
//! connections. Generated by the LLM from a folder (see [`super::ai`]) and saved by
//! [`super::store`].

use std::path::PathBuf;

use serde::{Deserialize, Deserializer, Serialize};

#[derive(Clone, Copy, PartialEq, Eq, Debug, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Kind {
    Surface,
    Service,
    Data,
    Package,
    External,
    Tooling,
}

impl Kind {
    /// Index in [`LANES`].
    pub fn lane(self) -> usize {
        match self {
            Kind::Surface => 0,
            Kind::Service => 1,
            Kind::Data | Kind::External => 2,
            Kind::Package => 3,
            Kind::Tooling => 4,
        }
    }
}

/// Lenient: unknown kinds become `Service`.
impl<'de> Deserialize<'de> for Kind {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let s = String::deserialize(d)?;
        Ok(match s.trim().to_ascii_lowercase().as_str() {
            "surface" | "client" | "frontend" | "ui" => Kind::Surface,
            "data" | "database" | "storage" => Kind::Data,
            "package" | "library" | "lib" => Kind::Package,
            "external" => Kind::External,
            "tooling" | "infra" | "infrastructure" => Kind::Tooling,
            _ => Kind::Service,
        })
    }
}

pub const LANES: [&str; 5] = [
    "Clients",
    "Runtime services",
    "Data & external systems",
    "Shared packages",
    "Infra & tooling",
];

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Node {
    pub id: String,
    pub name: String,
    /// Repositories whose code is this node (`name` or `owner/name`).
    #[serde(default)]
    pub repos: Vec<String>,
    #[serde(default = "default_kind")]
    pub kind: Kind,
    #[serde(default)]
    pub description: String,
}

fn default_kind() -> Kind {
    Kind::Service
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Edge {
    pub from: String,
    pub to: String,
    #[serde(default)]
    pub label: String,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct ServiceMap {
    /// Derived from the folder path: regenerating the same folder replaces the map.
    pub id: String,
    pub name: String,
    /// The folder the map was generated from.
    pub folder: PathBuf,
    pub created_at: i64,
    pub provider: String,
    pub nodes: Vec<Node>,
    pub edges: Vec<Edge>,
    /// Who is exposed to each part of the system; guides the LLM's `audience.facing` rating.
    pub notes: Vec<String>,
}

/// `owner/name` becomes `name`, lowercased.
pub fn repo_name(repo: &str) -> String {
    repo.trim().trim_end_matches(".git").rsplit('/').next().unwrap_or(repo).to_ascii_lowercase()
}

impl ServiceMap {
    pub fn node(&self, id: &str) -> Option<&Node> {
        self.nodes.iter().find(|n| n.id == id)
    }

    /// Services whose code lives in `repo` (`owner/name` or `name`).
    pub fn nodes_for_repo(&self, repo: &str) -> Vec<&Node> {
        let name = repo_name(repo);
        self.nodes
            .iter()
            .filter(|n| n.repos.iter().any(|r| repo_name(r) == name))
            .collect()
    }

    pub fn has_repo(&self, repo: &str) -> bool {
        !self.nodes_for_repo(repo).is_empty()
    }

    /// Nodes that call / depend on `id` (incoming edges).
    pub fn dependents<'a>(&'a self, id: &'a str) -> impl Iterator<Item = &'a str> + 'a {
        self.edges.iter().filter(move |e| e.to == id).map(|e| e.from.as_str())
    }
}

/// A stable id for the map of `folder`: its name plus a hash of its full path.
pub fn map_id(folder: &std::path::Path) -> String {
    let name: String = folder
        .file_name()
        .map(|n| n.to_string_lossy().to_ascii_lowercase())
        .unwrap_or_default()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
        .collect();
    // FNV-1a: stable across runs and Rust versions.
    let hash = folder
        .to_string_lossy()
        .bytes()
        .fold(0xcbf2_9ce4_8422_2325_u64, |h, b| (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3));
    format!("{}-{:08x}", name.trim_matches('-'), hash as u32)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_repos_with_or_without_owner() {
        let map = ServiceMap {
            nodes: vec![Node {
                id: "api".into(),
                name: "API".into(),
                repos: vec!["Acme/Api".into()],
                kind: Kind::Service,
                description: String::new(),
            }],
            ..Default::default()
        };
        assert!(map.has_repo("acme/api"));
        assert!(map.has_repo("other-org/API"));
        assert!(map.has_repo("api"));
        assert!(!map.has_repo("acme/web"));
    }

    #[test]
    fn lenient_kind() {
        let n: Node = serde_json::from_str(r#"{"id":"a","name":"A","kind":"Library"}"#).unwrap();
        assert_eq!(n.kind, Kind::Package);
        let n: Node = serde_json::from_str(r#"{"id":"a","name":"A","kind":"whatever"}"#).unwrap();
        assert_eq!(n.kind, Kind::Service);
    }

    #[test]
    fn map_id_is_stable_and_distinct() {
        let a = map_id(std::path::Path::new("/x/My Workspace"));
        assert_eq!(a, map_id(std::path::Path::new("/x/My Workspace")));
        assert!(a.starts_with("my-workspace-"));
        assert_ne!(a, map_id(std::path::Path::new("/y/My Workspace")));
    }
}
